INSERT INTO products (name, price, old_price, image_url, rating, type, style, description, colors, sizes, images, created_at) VALUES ('classic marni red & black suit', 251.99, NULL, 'https://cdn.dummyjson.com/product-images/womens-dresses/marni-red-%26-black-suit/thumbnail.webp', 5.0, 'dresses', 'formal', 'The Marni Red & Black Suit is a sophisticated and fashion-forward suit ensemble. With a combination of red and black tones, it showcases a modern design for a bold and confident look.', '[{"name": "Green", "hex": "#00C12B"}, {"name": "Red", "hex": "#F50606"}, {"name": "Orange", "hex": "#F57906"}, {"name": "Cyan", "hex": "#06CAF5"}]'::jsonb, ARRAY['Small','Medium','Large','X-Large'], ARRAY['https://cdn.dummyjson.com/product-images/womens-dresses/marni-red-%26-black-suit/1.webp','https://cdn.dummyjson.com/product-images/womens-dresses/marni-red-%26-black-suit/2.webp','https://cdn.dummyjson.com/product-images/womens-dresses/marni-red-%26-black-suit/3.webp','https://cdn.dummyjson.com/product-images/womens-dresses/marni-red-%26-black-suit/4.webp'], now() - interval '27 days');
