INSERT INTO reviews (product_id, author, rating, body, created_at)
SELECT p.product_id, r.author, r.rating, r.body, now() - (r.days || ' days')::interval - (p.product_id || ' hours')::interval
FROM products p
CROSS JOIN (VALUES
  ('Samantha D.', 4, 'I absolutely love this! The design is unique and the fabric feels so comfortable. It has become my favorite go-to piece.', 5),
  ('Alex M.', 5, 'Exceeded my expectations. The colors are vibrant and the quality is top-notch. Definitely getting another one.', 6),
  ('Ethan R.', 3, 'A must-have for anyone who appreciates good design. The fit is great, though the sizing runs a little small.', 7),
  ('Olivia P.', 4, 'Great value for the price. Simple, stylish and the fabric is soft. I get compliments every time I wear it.', 8),
  ('Liam K.', 5, 'A fusion of comfort and creativity. Soft fabric, thoughtful details and it looks like the photos.', 9),
  ('Ava H.', 4, 'Beautiful piece and the stitching is well done. Delivery was quick too. Would recommend.', 10),
  ('Noah W.', 3, 'Nice overall, but the color was slightly different from the photos. Still happy with the purchase.', 11),
  ('Mia T.', 5, 'Perfect for any occasion. It washes well and kept its shape after several cycles.', 12)
) AS r(author, rating, body, days);
